-- Banco EXTERNO de exemplo da Central de Dados (NÃO é o banco interno da INIA).
-- Simula o banco de um cliente: colaboradores e medições diárias, com um usuário SOMENTE LEITURA.
-- Dados fictícios e determinísticos (30 colaboradores, 560 medições). Só para avaliação local.

-- Executado pelo serviço example-sqlserver-init (sqlcmd) depois que o SQL Server está de pé.
if db_id('inia_exemplo') is null create database inia_exemplo;
go
use inia_exemplo;
go
if object_id('dbo.colaboradores') is null
begin
create table dbo.colaboradores (
  matricula varchar(20) not null primary key,
  nome nvarchar(120) not null,
  nivel varchar(20) not null,
  cargo nvarchar(120),
  gestor_matricula varchar(20),
  situacao varchar(20),
  data_admissao date,
  atualizado_em datetime2(7) not null
);
create table dbo.medicoes_diarias (
  id bigint not null primary key,
  matricula varchar(20) not null,
  indicador varchar(40) not null,
  data_referencia date not null,
  valor decimal(12,2),
  atualizado_em datetime2(7) not null
);
end
go
if not exists (select 1 from dbo.medicoes_diarias where id = 1)
go

if object_id('dbo.vw_colaboradores_em_producao') is null
exec('create view dbo.vw_colaboradores_em_producao as select matricula, nome, nivel, cargo, gestor_matricula, data_admissao, atualizado_em from dbo.colaboradores where situacao = ''EM_PRODUCAO''');
go
-- $(READER_PASSWORD): variável do sqlcmd (-v no compose.yaml), vinda de INIA_EXAMPLES_READER_PASSWORD — nunca do código.
if not exists (select 1 from sys.server_principals where name = 'inia_leitura')
  create login inia_leitura with password = '$(READER_PASSWORD)', check_policy = off;
go
if not exists (select 1 from sys.database_principals where name = 'inia_leitura')
begin
  create user inia_leitura for login inia_leitura;
  alter role db_datareader add member inia_leitura;
end
go
